Breakdown.PotentialShape.allComponents =
  {Breakdown.PotentialShape.PotComponent.plus, Breakdown.PotentialShape.PotComponent.minus,
    Breakdown.PotentialShape.PotComponent.axial}

∀ {f : Breakdown.Space → ℂ} {C : ℝ},
  Breakdown.PotentialShape.PressureWeak.Internal.ShellSlope f C →
    ∀ {ε : ℝ}, 0 < ε → ∀ (R : ℝ), ∃ K, LipschitzOnWith K (fun y => (f y).re) {y | ε ≤ ‖y‖ ∧ ‖y‖ ≤ R}

∀ {k count : ℕ} {piece : Fin count → (Fin k → ℝ) → ℝ → Breakdown.Space → Breakdown.Space}
  {pieceGrad : Fin count → (Fin k → ℝ) → ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {cubicForm : Fin count → Bool} {supNum gradNum : Fin count → ℝ} {count_1 : ℕ}
  {piece_1 : Fin count_1 → (Fin k → ℝ) → ℝ → Breakdown.Space → Breakdown.Space}
  {pieceGrad_1 : Fin count_1 → (Fin k → ℝ) → ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {cubicForm_1 : Fin count_1 → Bool} {supNum_1 gradNum_1 : Fin count_1 → ℝ},
  { count := count, piece := piece, pieceGrad := pieceGrad, cubicForm := cubicForm, supNum := supNum,
        gradNum := gradNum } =
      { count := count_1, piece := piece_1, pieceGrad := pieceGrad_1, cubicForm := cubicForm_1, supNum := supNum_1,
        gradNum := gradNum_1 } →
    count = count_1 ∧
      piece ≍ piece_1 ∧ pieceGrad ≍ pieceGrad_1 ∧ cubicForm ≍ cubicForm_1 ∧ supNum ≍ supNum_1 ∧ gradNum ≍ gradNum_1

